class Kullanici:
  def __init__(self):
    self.__yas = 0

  def yas_Ayarla(self, yeni_yas):
    if yeni_yas > 0: # Negatif yaş girilmesini engelledik
      self.__yas = yeni_yas
    else:
      print('Yaş negatif olamaz!')

  def yas_Getir(self):
    return self.__yas

k = Kullanici()
k.yas_Ayarla(-5)
k.yas_Ayarla(25)
print(k.yas_Getir())
